subroutine fortran_bbi_kick (x, y, sigma, nk, dnk, linear_kick) bind(c)

  use array_desc_mod
  implicit none
  ! ** In parameters **
  real(c_double) :: x  ! 0D_NOT_real
  real(rp) :: f_x
  real(c_double) :: y  ! 0D_NOT_real
  real(rp) :: f_y
  type(array_descriptor_t), intent(in) :: sigma
  real(rp) :: f_sigma(2)
  real(c_double), pointer :: f_sigma_ptr(:)
  type(c_ptr), intent(in), value :: linear_kick  ! 0D_NOT_logical
  logical(c_bool), pointer :: f_linear_kick
  logical, target :: f_linear_kick_native
  logical, pointer :: f_linear_kick_native_ptr
  logical(c_bool), pointer :: f_linear_kick_ptr
  ! ** Out parameters **
  type(array_descriptor_t), intent(in) :: nk
  real(rp) :: f_nk(2)
  real(c_double), pointer :: f_nk_ptr(:)
  type(array_descriptor_t), intent(in) :: dnk
  real(rp) :: f_dnk(2,2)
  real(c_double), pointer :: f_dnk_ptr(:)
  ! ** End of parameters **
  ! in: f_x 0D_NOT_real
  f_x = x
  ! in: f_y 0D_NOT_real
  f_y = y
  !! general array (1D_NOT_real) in
  if (c_associated(sigma%data_ptr)) then
    call c_f_pointer(sigma%data_ptr, f_sigma_ptr, [sigma%dims(1)])
    f_sigma = f_sigma_ptr(:)
  else
    f_sigma_ptr => null()
  endif
  !! general array (1D_NOT_real) out
  if (c_associated(nk%data_ptr)) then
    call c_f_pointer(nk%data_ptr, f_nk_ptr, [nk%dims(1)])
    ! output-only
  else
    f_nk_ptr => null()
  endif
  !! general array (2D_NOT_real) out
  if (c_associated(dnk%data_ptr)) then
    call c_f_pointer(dnk%data_ptr, f_dnk_ptr, [product(dnk%dims(1:dnk%rank))])
    ! output-only
  else
    f_dnk_ptr => null()
  endif
  ! in: f_linear_kick 0D_NOT_logical
  if (c_associated(linear_kick)) then
    call c_f_pointer(linear_kick, f_linear_kick_ptr)
    f_linear_kick_native = f_linear_kick_ptr
    f_linear_kick_native_ptr => f_linear_kick_native
  else
    f_linear_kick_native_ptr => null()
  endif
  call bbi_kick(f_x, f_y, f_sigma, f_nk, f_dnk, f_linear_kick_native_ptr)

  ! out: f_nk 1D_NOT_real
  if (c_associated(nk%data_ptr)) then
    call c_f_pointer(nk%data_ptr, f_nk_ptr, [nk%dims(1)])
    f_nk_ptr = f_nk(:)
  endif
  ! out: f_dnk 2D_NOT_real
  if (c_associated(dnk%data_ptr)) f_dnk_ptr = mat2vec(f_dnk, product(dnk%dims(1:dnk%rank)))
end subroutine
