subroutine fortran_cbar_to_c (cbar_mat, a, b, c_mat) bind(c)

  use array_desc_mod
  use bmad_struct, only: twiss_struct
  implicit none
  ! ** In parameters **
  type(array_descriptor_t), intent(in) :: cbar_mat
  real(rp) :: f_cbar_mat(2,2)
  real(c_double), pointer :: f_cbar_mat_ptr(:)
  type(c_ptr), value :: a  ! 0D_NOT_type
  type(twiss_struct), pointer :: f_a
  type(c_ptr), value :: b  ! 0D_NOT_type
  type(twiss_struct), pointer :: f_b
  ! ** Out parameters **
  type(array_descriptor_t), intent(in) :: c_mat
  real(rp) :: f_c_mat(2,2)
  real(c_double), pointer :: f_c_mat_ptr(:)
  ! ** End of parameters **
  !! general array (2D_NOT_real) in
  if (c_associated(cbar_mat%data_ptr)) then
    call c_f_pointer(cbar_mat%data_ptr, f_cbar_mat_ptr, [product(cbar_mat%dims(1:cbar_mat%rank))])
    call vec2mat(f_cbar_mat_ptr, f_cbar_mat)
  else
    f_cbar_mat_ptr => null()
  endif
  ! in: f_a 0D_NOT_type
  if (.not. c_associated(a)) return
  call c_f_pointer(a, f_a)
  ! in: f_b 0D_NOT_type
  if (.not. c_associated(b)) return
  call c_f_pointer(b, f_b)
  !! general array (2D_NOT_real) out
  if (c_associated(c_mat%data_ptr)) then
    call c_f_pointer(c_mat%data_ptr, f_c_mat_ptr, [product(c_mat%dims(1:c_mat%rank))])
    ! output-only
  else
    f_c_mat_ptr => null()
  endif
  call cbar_to_c(f_cbar_mat, f_a, f_b, f_c_mat)

  ! out: f_c_mat 2D_NOT_real
  if (c_associated(c_mat%data_ptr)) f_c_mat_ptr = mat2vec(f_c_mat, product(c_mat%dims(1:c_mat%rank)))
end subroutine
