subroutine fortran_element_slice_iterator (ele, param, i_slice, n_slice_tot, sliced_ele, &
    s_start, s_end) bind(c)

  use array_desc_mod
  use bmad_struct, only: ele_struct, lat_param_struct
  implicit none
  ! ** In parameters **
  type(c_ptr), value :: ele  ! 0D_NOT_type
