subroutine fortran_form_digested_bmad_file_name (lat_file, digested_file, full_lat_file, &
    use_line) bind(c)

  use array_desc_mod
  implicit none
  ! ** In parameters **
  type(c_ptr), intent(in), value :: lat_file
  character(len=4096), target :: f_lat_file
