  ! out: f_beam 0D_NOT_type
  if (.not. c_associated(beam)) then
    call c_f_pointer(err_flag, f_err_flag_ptr)
    f_err_flag_ptr = .true.
    return
  endif
  call c_f_pointer(beam, f_beam)
  ! out: f_err_flag 0D_NOT_logical
  if (c_associated(err_flag)) then
    call c_f_pointer(err_flag, f_err_flag_ptr)
  else
    f_err_flag_ptr => null()
  endif
  ! in: f_modes 0D_NOT_type
