  real(rp) :: f_B(6,6)
  real(c_double), pointer :: f_B_ptr(:)
  type(array_descriptor_t), intent(in) :: V
  real(rp) :: f_V(6,6)
  real(c_double), pointer :: f_V_ptr(:)
