  if (c_associated(orb0_arr%data_ptr)) then
    call c_f_pointer(orb0_arr%data_ptr, f_orb0_arr_ptr, [orb0_arr%dims(1)])
    f_orb0_arr(0:) => f_orb0_arr_ptr
  else
    f_orb0_arr => null()
