  real(c_double) :: offset  ! 0D_NOT_real
  real(rp) :: f_offset
  type(c_ptr), value :: param  ! 0D_NOT_type
  type(lat_param_struct), pointer :: f_param
  logical(c_bool) :: include_upstream_end  ! 0D_NOT_logical
