  type(c_ptr), intent(in), value :: stable  ! 0D_NOT_logical
  logical :: f_stable
  logical(c_bool), pointer :: f_stable_ptr
  type(c_ptr), intent(in), value :: growth_rate  ! 0D_NOT_real
  real(rp) :: f_growth_rate
  real(c_double), pointer :: f_growth_rate_ptr
