  if (c_associated(track%data_ptr)) then
    call c_f_pointer(track%data_ptr, f_track_ptr, [track%dims(1)])
    f_track => f_track_ptr
  else
    f_track => null()
  endif
  ! in: f_i_dim 0D_NOT_integer
  f_i_dim = i_dim
  ! out: f_track0 0D_NOT_type
  if (.not. c_associated(track0)) then
    call c_f_pointer(err_flag, f_err_flag_ptr)
    f_err_flag_ptr = .true.
