    xfer_nodamp_mat, err_flag, closed_orbit, rad_int_branch) bind(c)

  use array_desc_mod
  use bmad_struct, only: coord_struct, ele_struct, normal_modes_struct, rad_int_branch_struct, rad_map_struct
  implicit none
  ! ** In parameters **
  type(c_ptr), value :: ele1  ! 0D_NOT_type
