    ! output-only
  else
    f_xfer_nodamp_mat_ptr => null()
  endif
  !! type array (1D_NOT_type)
  if (c_associated(closed_orbit%data_ptr)) then
    call c_f_pointer(closed_orbit%data_ptr, f_closed_orbit_ptr, [closed_orbit%dims(1)])
