    beam_init, closed_orb) bind(c)

  use array_desc_mod
  use bmad_struct, only: beam_init_struct, branch_struct, coord_struct, normal_modes_struct
  implicit none
  ! ** In parameters **
  logical(c_bool) :: calc_on  ! 0D_NOT_logical
