  endif
  ! in: f_make_matrix 0D_NOT_logical
  if (c_associated(make_matrix)) then
    call c_f_pointer(make_matrix, f_make_matrix_ptr)
    f_make_matrix_native = f_make_matrix_ptr
    f_make_matrix_native_ptr => f_make_matrix_native
  else
