  !! general array (2D_NOT_real) out
  if (c_associated(w_surface%data_ptr)) then
    call c_f_pointer(w_surface%data_ptr, f_w_surface_ptr, [product(w_surface%dims(1:w_surface%rank))])
    ! output-only
