  type(c_ptr), intent(in), value :: err  ! 0D_NOT_logical
  logical :: f_err
  logical(c_bool), pointer :: f_err_ptr
  ! ** Inout parameters **
  type(c_ptr), value :: ele_end  ! 0D_NOT_type
