    f_err_flag_ptr = .true.
    return
  endif
  call c_f_pointer(lat, f_lat)
  ! in: f_ref_orb0 0D_NOT_type
  if (.not. c_associated(ref_orb0)) then
    call c_f_pointer(err_flag, f_err_flag_ptr)
    f_err_flag_ptr = .true.
    return
